        "query": "index=agentsec_telemetry sourcetype=otel:agentic:json earliest=0 (\"agentsec.run.id\"=\"$live_run_id$\" OR \"agentsec.run.id\"=\"$run_id$\")\n| eval run_id=mvindex(mvdedup('agentsec.run.id'),0)\n| eval selected_run=if(\"$live_run_id$\"==\"none\",\"$run_id$\",\"$live_run_id$\")\n| where run_id==selected_run\n| eval mode=mvindex(mvdedup('agentsec.testbed.mode'),0)\n| eval profile=mvindex(mvdedup('agentsec.security.profile'),0)\n| stats dc(_raw) as indexed_events, values(mode) as mode, values(profile) as profile by run_id\n| eval evidence_state=\"INDEXED EVIDENCE PRESENT\"\n| eval current_evidence=if(\"$live_run_id$\"==\"none\",\"REPLAY — recorded \"+mode+\" example (not your run)\",\"LIVE — your \"+mode+\" experiment\")\n| eval selector_in_use=if(\"$live_run_id$\"==\"none\",\"REPLAY example selector\",\"LIVE box (the REPLAY example selector is ignored)\")\n| table current_evidence, selector_in_use, run_id, mode, profile, indexed_events, evidence_state"
